        private static readonly float[][][] Tangents = BuildTangents();

        /// <summary>Есть ли у трюка хореография (у барспина — нет).</summary>
        public static bool Has(int trick) => trick >= 0 && trick < Keys.Length && Keys[trick] != null;

        /// <summary>Есть ли у трюка ключи этого канала.</summary>
        public static bool HasChannel(int trick, Ch ch) => Has(trick) && Keys[trick][(int)ch] != null;

        /// <summary>Значение канала в момент t (0…1).</summary>
        public static float Get(int trick, Ch ch, float t)
        {
            if (!Has(trick)) return 0f;
            float[] k = Keys[trick][(int)ch];
            if (k == null || k.Length < 2) return 0f;
            int n = k.Length / 2;
            if (t <= k[0]) return k[1];
            if (t >= k[2 * n - 2]) return k[2 * n - 1];
            float[] m = Tangents[trick][(int)ch];
            int i = 0;
            while (k[2 * i + 2] < t) i++;
            float t0 = k[2 * i], v0 = k[2 * i + 1], t1 = k[2 * i + 2], v1 = k[2 * i + 3];
            float h = t1 - t0, u = (t - t0) / h, u2 = u * u, u3 = u2 * u;
            return (2f * u3 - 3f * u2 + 1f) * v0 + (u3 - 2f * u2 + u) * h * m[i] + (-2f * u3 + 3f * u2) * v1 + (u3 - u2) * h * m[i + 1];
        }

        /// <summary>Монотонные касательные (Fritsch–Carlson): плавно и без «перелётов» между ключами.</summary>
        private static float[][][] BuildTangents()
        {
            var all = new float[Keys.Length][][];
            for (int tr = 0; tr < Keys.Length; tr++)
            {
                if (Keys[tr] == null) continue;
                all[tr] = new float[Count][];
                for (int c = 0; c < Count; c++)
                {
                    float[] k = Keys[tr][c];
                    if (k == null) continue;
                    int n = k.Length / 2;
                    var m = new float[n];
                    var d = new float[Mathf.Max(0, n - 1)];
                    for (int i = 0; i < n - 1; i++) d[i] = (k[2 * i + 3] - k[2 * i + 1]) / (k[2 * i + 2] - k[2 * i]);
                    for (int i = 1; i < n - 1; i++) m[i] = d[i - 1] * d[i] <= 0f ? 0f : (d[i - 1] + d[i]) * 0.5f;
                    for (int i = 0; i < n - 1; i++)
                    {
                        if (d[i] == 0f) { m[i] = m[i + 1] = 0f; continue; }
                        float a = m[i] / d[i], b = m[i + 1] / d[i], s = a * a + b * b;
                        if (s > 9f) { float q = 3f / Mathf.Sqrt(s); m[i] = q * a * d[i]; m[i + 1] = q * b * d[i]; }
                    }
                    all[tr][c] = m;
                }
            }
            return all;
        }
    }
